	@Test
	public void testSourceSelectionCache_setBindings() throws Exception {

		var bob = Values.iri("http://example.com/bob");

		List<Endpoint> endpoints = prepareTest(
				Arrays.asList("/tests/basic/data_emptyStore.ttl", "/tests/basic/data_emptyStore.ttl"));

		Repository repo1 = getRepository(1);
		Repository repo2 = getRepository(2);

		String repo1Id = endpoints.get(0).getId();

		try (RepositoryConnection con = repo1.getConnection()) {
			con.add(bob, RDF.TYPE, FOAF.PERSON);
		}

		try (RepositoryConnection con = repo2.getConnection()) {
			con.add(FOAF.PERSON, RDF.TYPE, OWL.CLASS);
		}

		Repository fedxRepo = fedxRule.getRepository();

		try (var conn = fedxRepo.getConnection()) {

			TupleQuery tq = conn.prepareTupleQuery("SELECT * WHERE { ?s a ?type }");
			tq.setBinding("s", bob);

			try (var tqr = tq.evaluate()) {
				// just consume the result
				Assertions.assertEquals(Set.of(FOAF.PERSON),
						tqr.stream().map(bs -> bs.getValue("type")).collect(Collectors.toSet()));
			}
		}

		SourceSelectionCache cache = federationContext().getSourceSelectionCache();

		var assurance = cache.getAssurance(new SubQuery(bob, RDF.TYPE, null),
				federationContext().getEndpointManager().getEndpoint(repo1Id));

		// we expect that the source selection cache can assure statements
		Assertions.assertEquals(StatementSourceAssurance.HAS_REMOTE_STATEMENTS, assurance);
	}

	@Test
	public void scopedOptionalClosesLeftIterationWhenRightPreparationFails() throws Exception {
		FedXRepository repository = FedXFactory.newFederation().withMembers(new ArrayList<Endpoint>()).create();
		repository.init();
		try {
			FederationContext context = repository.getFederationContext();
			SingletonSet leftArg = new SingletonSet();
			SingletonSet rightArg = new SingletonSet();
			AtomicInteger openCount = new AtomicInteger();
			AtomicInteger closeCount = new AtomicInteger();
			QueryEvaluationException failure = new QueryEvaluationException("right preparation failed");
			FederationEvaluationStrategy strategy = new FederationEvaluationStrategy(context) {
				@Override
				public QueryEvaluationStep precompile(TupleExpr expr, QueryEvaluationContext evaluationContext)
						throws QueryEvaluationException {
					if (expr == leftArg) {
						return bindings -> {
							openCount.incrementAndGet();
							return new CloseableIteratorIteration<>(Collections.emptyIterator()) {
								@Override
								protected void handleClose() {
									closeCount.incrementAndGet();
								}
							};
						};
					}
					if (expr == rightArg) {
						throw failure;
					}
					return super.precompile(expr, evaluationContext);
				}
			};
			QueryInfo queryInfo = new QueryInfo(null, null, QueryType.SELECT, 0, false, context, strategy, null);
			FedXLeftJoin leftJoin = new FedXLeftJoin(new LeftJoin(leftArg, rightArg), queryInfo);
			QueryEvaluationContext scoped = new ActiveGraphQueryEvaluationContext(
					new QueryEvaluationContext.Minimal(null),
					new QueryEvaluationContext.ActiveGraph(Values.iri("urn:active"), null));
			QueryEvaluationStep prepared = strategy.precompile(leftJoin, scoped);

			QueryEvaluationException thrown = Assertions.assertThrows(QueryEvaluationException.class,
					() -> prepared.evaluate(EmptyBindingSet.getInstance()));
			Assertions.assertSame(failure, thrown);
			Assertions.assertEquals(1, openCount.get());
			Assertions.assertEquals(1, closeCount.get());
		} finally {
			repository.shutDown();
		}
	}

	@Test
	public void closingOneOverlappingPreparedNaryUnionLeavesAnotherUsable() throws Exception {
		FedXRepository repository = FedXFactory.newFederation().withMembers(new ArrayList<Endpoint>()).create();
		repository.init();
		CountDownLatch firstTasksStarted = new CountDownLatch(2);
		CountDownLatch secondTasksStarted = new CountDownLatch(2);
		CountDownLatch releaseTasks = new CountDownLatch(1);
		QueryInfo[] queryInfo = new QueryInfo[1];
		var firstArgument = new SingletonSet();
		var secondArgument = new SingletonSet();
		try {
			FederationContext context = repository.getFederationContext();
			FederationEvaluationStrategy strategy = new FederationEvaluationStrategy(context) {
				@Override
				public QueryEvaluationStep precompile(TupleExpr expr, QueryEvaluationContext evaluationContext)
						throws QueryEvaluationException {
					if (expr == firstArgument) {
						return bindings -> blockedUnionRow(bindings, "left", firstTasksStarted, secondTasksStarted,
								releaseTasks);
					}
					if (expr == secondArgument) {
						return bindings -> blockedUnionRow(bindings, "right", firstTasksStarted, secondTasksStarted,
								releaseTasks);
					}
					return super.precompile(expr, evaluationContext);
				}
			};
			queryInfo[0] = new QueryInfo(null, null, QueryType.SELECT, 0, false, context, strategy, null);
			NUnion union = new NUnion(List.of(firstArgument, secondArgument), queryInfo[0]);
			QueryEvaluationStep prepared = strategy.precompile(union, new QueryEvaluationContext.Minimal(null));
			MapBindingSet firstBindings = new MapBindingSet();
			firstBindings.addBinding("invocation", Values.literal("first"));
			MapBindingSet secondBindings = new MapBindingSet();
			secondBindings.addBinding("invocation", Values.literal("second"));

			var first = prepared.evaluate(firstBindings);
			Assertions.assertTrue(firstTasksStarted.await(10, TimeUnit.SECONDS),
					"both tasks from the first evaluation should start before the second evaluation");
			var second = prepared.evaluate(secondBindings);
			try {
				Assertions.assertTrue(secondTasksStarted.await(10, TimeUnit.SECONDS),
						"both tasks from the second evaluation should overlap the first evaluation");
				first.close();
				releaseTasks.countDown();
				assertThat(QueryResults.asList(second)).containsExactlyInAnyOrder(
						unionRow("second", "left"), unionRow("second", "right"));
			} finally {
				releaseTasks.countDown();
				first.close();
				second.close();
			}
		} finally {
			releaseTasks.countDown();
			if (queryInfo[0] != null) {
				queryInfo[0].close();
			}
			repository.shutDown();
		}
	}

	@Test
	public void ordinaryAndScopedJoinHooksKeepTheirDispatchContracts() throws Exception {
		FedXRepository repository = FedXFactory.newFederation().withMembers(new ArrayList<Endpoint>()).create();
		repository.init();
		List<QueryInfo> queryInfos = new ArrayList<>();
		try {
			FederationContext context = repository.getFederationContext();
			class HookStrategy extends FederationEvaluationStrategy {
				private int legacyJoinCalls;
				private int scopedJoinCalls;
				private int legacyLeftJoinCalls;
				private int scopedLeftJoinCalls;

				HookStrategy() {
					super(context);
				}

				@Override
				public CloseableIteration<BindingSet> executeJoin(ControlledWorkerScheduler<BindingSet> scheduler,
						CloseableIteration<BindingSet> left, TupleExpr right, Set<String> joinVars, BindingSet bindings,
						QueryInfo queryInfo) throws QueryEvaluationException {
					legacyJoinCalls++;
					return super.executeJoin(scheduler, left, right, joinVars, bindings, queryInfo);
				}

				@Override
				public CloseableIteration<BindingSet> executeJoin(ControlledWorkerScheduler<BindingSet> scheduler,
						CloseableIteration<BindingSet> left, TupleExpr right, Set<String> joinVars, BindingSet bindings,
						QueryInfo queryInfo, QueryEvaluationContext evaluationContext) throws QueryEvaluationException {
					scopedJoinCalls++;
					return super.executeJoin(scheduler, left, right, joinVars, bindings, queryInfo, evaluationContext);
				}

				@Override
				protected CloseableIteration<BindingSet> executeLeftJoin(
						ControlledWorkerScheduler<BindingSet> scheduler, CloseableIteration<BindingSet> left,
						LeftJoin leftJoin, BindingSet bindings, QueryInfo queryInfo) throws QueryEvaluationException {
					legacyLeftJoinCalls++;
					return super.executeLeftJoin(scheduler, left, leftJoin, bindings, queryInfo);
				}

				@Override
				protected CloseableIteration<BindingSet> executeLeftJoin(
						ControlledWorkerScheduler<BindingSet> scheduler, CloseableIteration<BindingSet> left,
						LeftJoin leftJoin, BindingSet bindings, QueryInfo queryInfo,
						QueryEvaluationContext evaluationContext) throws QueryEvaluationException {
					scopedLeftJoinCalls++;
					return super.executeLeftJoin(scheduler, left, leftJoin, bindings, queryInfo, evaluationContext);
				}
			}
			HookStrategy strategy = new HookStrategy();
			QueryEvaluationContext ordinary = new QueryEvaluationContext.Minimal(null);
			QueryEvaluationContext scoped = new ActiveGraphQueryEvaluationContext(ordinary,
					new QueryEvaluationContext.ActiveGraph(Values.iri("urn:active"), null));
			QueryEvaluationContext inheritedProjection = new DatasetQueryEvaluationContext(ordinary, null, true);

			for (QueryEvaluationContext evaluationContext : List.of(ordinary, scoped, inheritedProjection)) {
				QueryInfo joinInfo = new QueryInfo(null, null, QueryType.SELECT, 0, false, context, strategy, null);
				queryInfos.add(joinInfo);
				NJoin join = new NJoin(List.of(new SingletonSet(), new SingletonSet()), joinInfo);
				try (var rows = strategy.precompile(join, evaluationContext).evaluate(EmptyBindingSet.getInstance())) {
					assertThat(QueryResults.asList(rows)).containsExactly(EmptyBindingSet.getInstance());
				}

				QueryInfo leftJoinInfo = new QueryInfo(null, null, QueryType.SELECT, 0, false, context, strategy, null);
				queryInfos.add(leftJoinInfo);
				FedXLeftJoin leftJoin = new FedXLeftJoin(new LeftJoin(new SingletonSet(), new SingletonSet()),
						leftJoinInfo);
				try (var rows = strategy.precompile(leftJoin, evaluationContext)
						.evaluate(EmptyBindingSet.getInstance())) {
					assertThat(QueryResults.asList(rows)).containsExactly(EmptyBindingSet.getInstance());
				}
			}

			Assertions.assertEquals(1, strategy.legacyJoinCalls);
			Assertions.assertEquals(3, strategy.scopedJoinCalls);
			Assertions.assertEquals(1, strategy.legacyLeftJoinCalls);
			Assertions.assertEquals(3, strategy.scopedLeftJoinCalls);
		} finally {
			queryInfos.forEach(QueryInfo::close);
			repository.shutDown();
		}
	}

	private static CloseableIteratorIteration<BindingSet> blockedUnionRow(BindingSet bindings, String branch,
			CountDownLatch firstTasksStarted, CountDownLatch secondTasksStarted, CountDownLatch releaseTasks)
			throws QueryEvaluationException {
		String invocation = bindings.getValue("invocation").stringValue();
		CountDownLatch tasksStarted = "first".equals(invocation) ? firstTasksStarted : secondTasksStarted;
		tasksStarted.countDown();
		try {
			if (!releaseTasks.await(10, TimeUnit.SECONDS)) {
				throw new QueryEvaluationException("Timed out waiting to release overlapping union task");
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new QueryEvaluationException("Union task was interrupted", e);
		}
		return new CloseableIteratorIteration<>(List.of(unionRow(invocation, branch)).iterator());
	}

	private static BindingSet unionRow(String invocation, String branch) {
		MapBindingSet row = new MapBindingSet(2);
		row.addBinding("invocation", Values.literal(invocation));
		row.addBinding("branch", Values.literal(branch));
		return row;
	}
